/*==========================================================================*/

Vin_Car_Type vin_lookup (void)        
{       
  UInt8 index = 0 ;

  do
  {      
     if(vin_match ( vin_table[index].vin_def , vin_info.vin.code ) == VIN_MATCH )
     {
       return vin_table[index].vin_car_type ;
     }

  }
  while(++index < VIN_TABLE_SIZE) ;  
  
  return VIN_NO_TYPE ;
}

